# frozen_string_literal: true

# Throwaway micro-benchmark: cost (ms) and number of inserted rows per fabricated record.
# Run: bundle exec rspec tmp/prof/fabricate_bench_spec.rb
require 'rails_helper'

RSpec.describe 'Fabricator costs', type: :model do # rubocop:disable RSpec/DescribeClass
  N = Integer(ENV.fetch('N', 30))

  def measure(name, &block)
    2.times(&block) # warm-up (autoloading, statement caches)
    inserts = Hash.new(0)
    sub = ActiveSupport::Notifications.subscribe('sql.active_record') do |*, payload|
      inserts[payload[:sql][/\AINSERT INTO "(\w+)"/, 1]] += 1 if payload[:sql].start_with?('INSERT')
    end
    started = Process.clock_gettime(Process::CLOCK_MONOTONIC)
    N.times(&block)
    elapsed = Process.clock_gettime(Process::CLOCK_MONOTONIC) - started
    ActiveSupport::Notifications.unsubscribe(sub)
    rows = inserts.transform_values { |v| (v.to_f / N).round(1) }.sort_by { |_, v| -v }.map { |t, v| "#{t}=#{v}" }.join(' ')
    puts format('%-28s %7.2fms  %s', name, elapsed * 1000 / N, rows)
  end

  it 'measures' do
    local = Fabricate(:account)
    remote = Fabricate(:account, domain: 'example.com')
    measure(':user') { Fabricate(:user) }
    measure(':account (local)') { Fabricate(:account) }
    measure(':account (remote)') { Fabricate(:account, domain: 'example.com') }
    measure(':status') { Fabricate(:status) }
    measure(':status, account: local') { Fabricate(:status, account: local) }
    measure(':status, account: remote') { Fabricate(:status, account: remote) }
    measure(':favourite') { Fabricate(:favourite) }
    measure(':follow') { Fabricate(:follow) }
    measure(':notification') { Fabricate(:notification) }
    measure(':access_token') { Fabricate(:accessible_access_token, resource_owner_id: local.user.id) }
    measure(':login_activity') { Fabricate(:login_activity) }
    measure(':custom_emoji') { Fabricate(:custom_emoji) }
    measure(':preview_card') { Fabricate(:preview_card) }
    measure(':media_attachment') { Fabricate(:media_attachment, account: local) }
    measure('User#password=') { User.new(password: '123456789') }
  end
end
