diffs = sa.map { |f, t| [f, t, sb.fetch(f, 0), t - sb.fetch(f, 0)] }.sort_by { |x| -x[3] }
diffs.first(12).each { |f, t1, t2, d| puts format('%-70s %6.2fs -> %6.2fs (-%.2fs)', f, t1, t2, d) }
puts "files slower by >0.3s: #{diffs.count { |x| x[3] < -0.3 }}"
EOF
